import{_ as r,C as d,o as e,c as l,a4 as i,b as c,w as s,a as n,E as p,a5 as h}from"./chunks/framework.BUqnS5H7.js";const u=JSON.parse('{"title":"服务注册与发现","description":"","frontmatter":{},"headers":[],"relativePath":"spring/09-distributed/chapter-03-service-discovery.md","filePath":"spring/09-distributed/chapter-03-service-discovery.md"}'),o={name:"spring/09-distributed/chapter-03-service-discovery.md"};function g(y,t,E,v,f,k){const a=d("Mermaid");return e(),l("div",null,[t[1]||(t[1]=i(`<h1 id="服务注册与发现" tabindex="-1" data-src-line="1" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">服务注册与发现 <a class="header-anchor" href="#服务注册与发现" aria-label="Permalink to &quot;服务注册与发现&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><p data-src-line="3" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">服务调用章节里的 <code>lb://order-service</code>、<code>@LoadBalanced</code>，全都依赖同一个前提，先要知道 <code>order-service</code> 现在有哪些存活实例。这个前提由注册中心提供。本章讲清楚注册中心解决什么问题、Nacos 怎么实现它，以及最容易踩的两个坑。</p></blockquote><h2 id="_1-为什么需要注册中心" tabindex="-1" data-src-line="5" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">1. 为什么需要注册中心 <a class="header-anchor" href="#_1-为什么需要注册中心" aria-label="Permalink to &quot;1. 为什么需要注册中心&quot;">​</a></h2><p data-src-line="7" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">假设 order-service 要调用 storage-service。没有注册中心时，只能把 storage-service 的地址写死在配置里：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://192.168.1.10:8080</span></span></code></pre></div><p data-src-line="14" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">这个写法撑不过第一次扩容。storage-service 从 1 个实例加到 10 个，地址从一台变成十台；某个实例重启后换到了别的端口；容器化部署后每次发布的 IP 都不一样。地址一旦写死，任何一次实例变化都要改配置、重启 order-service。</p><p data-src-line="16" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">注册中心把「服务现在在哪」从静态配置变成动态查询。它维护一张表，key 是服务名，value 是存活实例列表。服务启动时把自己登记进去，调用方按服务名查地址。</p>`,7)),(e(),c(h,null,{default:s(()=>[p(a,{id:"mermaid-21",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20P%20as%20%E6%9C%8D%E5%8A%A1%E6%8F%90%E4%BE%9B%E8%80%85%20storage-service%0A%20%20%20%20participant%20R%20as%20%E6%B3%A8%E5%86%8C%E4%B8%AD%E5%BF%83%20Nacos%0A%20%20%20%20participant%20C%20as%20%E6%9C%8D%E5%8A%A1%E6%B6%88%E8%B4%B9%E8%80%85%20order-service%0A%0A%20%20%20%20P-%3E%3ER%3A%201.%20%E5%90%AF%E5%8A%A8%E6%97%B6%E6%B3%A8%E5%86%8C%E5%AE%9E%E4%BE%8B%EF%BC%88IP%20%E5%8A%A0%E7%AB%AF%E5%8F%A3%EF%BC%89%0A%20%20%20%20loop%20%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%0A%20%20%20%20%20%20%20%20P--%3E%3ER%3A%202.%20%E5%BF%83%E8%B7%B3%E4%BF%9D%E6%B4%BB%EF%BC%88%E9%BB%98%E8%AE%A4%205%20%E7%A7%92%E4%B8%80%E6%AC%A1%EF%BC%89%0A%20%20%20%20end%0A%20%20%20%20C-%3E%3ER%3A%203.%20%E8%AE%A2%E9%98%85%20storage-service%0A%20%20%20%20R--%3E%3EC%3A%204.%20%E6%8E%A8%E9%80%81%E5%8F%AF%E7%94%A8%E5%AE%9E%E4%BE%8B%E5%88%97%E8%A1%A8%0A%20%20%20%20C-%3E%3EP%3A%205.%20%E7%9B%B4%E6%8E%A5%E8%B0%83%E7%94%A8%E6%9F%90%E4%B8%AA%E5%AE%9E%E4%BE%8B%0A%20%20%20%20P--%3E%3ER%3A%206.%20%E5%AE%95%E6%9C%BA%EF%BC%8C%E5%BF%83%E8%B7%B3%E4%B8%AD%E6%96%AD%0A%20%20%20%20R--%3E%3EC%3A%207.%20%E6%8E%A8%E9%80%81%E5%8F%98%E6%9B%B4%EF%BC%8C%E5%89%94%E9%99%A4%E5%AE%95%E6%9C%BA%E5%AE%9E%E4%BE%8B%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i(`<h2 id="_2-注册中心承担的四件事" tabindex="-1" data-src-line="35" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">2. 注册中心承担的四件事 <a class="header-anchor" href="#_2-注册中心承担的四件事" aria-label="Permalink to &quot;2. 注册中心承担的四件事&quot;">​</a></h2><p data-src-line="37" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">时序图里的七步可以归为四件事。</p><table tabindex="0"><thead data-src-line="39" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="39" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><th style="text-align:left;">动作</th><th style="text-align:left;">谁发起</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="41" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="41" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">服务注册</td><td style="text-align:left;">提供者</td><td style="text-align:left;">启动时把服务名、IP、端口、元数据登记到注册中心</td></tr><tr data-src-line="42" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">健康检查</td><td style="text-align:left;">提供者或注册中心</td><td style="text-align:left;">判断实例是否还活着，决定它是否留在列表里</td></tr><tr data-src-line="43" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">服务发现</td><td style="text-align:left;">消费者</td><td style="text-align:left;">按服务名拿到存活实例列表</td></tr><tr data-src-line="44" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">服务注销</td><td style="text-align:left;">提供者或注册中心</td><td style="text-align:left;">正常下线时主动摘除，异常宕机时靠健康检查剔除</td></tr></tbody></table><p data-src-line="46" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">四件事里最关键的是健康检查。注册中心不能只听服务「说自己起来了」，它需要持续确认这个实例是否真的还能用。健康检查做不好，就会出现调用方拿到一堆死地址。</p><h2 id="_3-nacos-discovery-集成" tabindex="-1" data-src-line="48" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">3. Nacos Discovery 集成 <a class="header-anchor" href="#_3-nacos-discovery-集成" aria-label="Permalink to &quot;3. Nacos Discovery 集成&quot;">​</a></h2><p data-src-line="50" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">依赖和配置都很薄。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;com.alibaba.cloud&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-cloud-starter-alibaba-nacos-discovery&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">order-service</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cloud</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    nacos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      discovery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        server-addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1:8848</span></span></code></pre></div><p data-src-line="69" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">Spring Cloud Alibaba 2021.x 起，<code>@EnableDiscoveryClient</code> 不再是必须的，引入依赖后自动生效。<code>spring.application.name</code> 就是注册到注册中心的服务名，调用方用这个名字发起 <code>lb://order-service</code> 调用。</p><p data-src-line="71" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">启动后可以在 Nacos 控制台的「服务列表」看到 order-service，以及它下面的实例。</p><h2 id="_4-临时实例与持久实例" tabindex="-1" data-src-line="73" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">4. 临时实例与持久实例 <a class="header-anchor" href="#_4-临时实例与持久实例" aria-label="Permalink to &quot;4. 临时实例与持久实例&quot;">​</a></h2><p data-src-line="75" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">这是 Nacos 区别于 Eureka 的核心设计，也是出问题最多的地方。</p><p data-src-line="77" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">Nacos 把实例分成两类，由 <code>ephemeral</code> 字段控制。默认是临时实例。</p><table tabindex="0"><thead data-src-line="79" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="79" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><th style="text-align:left;">维度</th><th style="text-align:left;">临时实例（默认）</th><th style="text-align:left;">持久实例</th></tr></thead><tbody data-src-line="81" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="81" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">配置</td><td style="text-align:left;"><code>ephemeral: true</code></td><td style="text-align:left;"><code>ephemeral: false</code></td></tr><tr data-src-line="82" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">健康检查</td><td style="text-align:left;">客户端心跳上报</td><td style="text-align:left;">服务端主动探测（TCP / HTTP / MySQL）</td></tr><tr data-src-line="83" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">判定节奏</td><td style="text-align:left;">心跳 5 秒一次，15 秒未收到标不健康，30 秒剔除</td><td style="text-align:left;">默认 20 秒探测一次</td></tr><tr data-src-line="84" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">存储</td><td style="text-align:left;">只存内存，重启即失</td><td style="text-align:left;">持久化到磁盘</td></tr><tr data-src-line="85" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">宕机处理</td><td style="text-align:left;">自动从列表剔除</td><td style="text-align:left;">只标不健康，不删除</td></tr><tr data-src-line="86" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">一致性模型</td><td style="text-align:left;">AP</td><td style="text-align:left;">CP</td></tr><tr data-src-line="87" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">弹性伸缩的业务服务</td><td style="text-align:left;">MySQL、Redis 等基础设施</td></tr></tbody></table><p data-src-line="89" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">两种实例的差别，本质是「宕机后谁负责把它踢出去」。</p><p data-src-line="91" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">临时实例靠心跳保活。客户端每 5 秒向服务端报一次心跳，服务端 15 秒没收到就标记不健康，30 秒还没收到就从列表剔除。业务服务用临时实例，进程被杀、机器断电，心跳自然中断，最迟 30 秒后调用方就拿不到这个死实例了。</p><p data-src-line="93" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">持久实例靠服务端反向探测。服务端主动去连实例的端口（TCP 探测）或请求健康接口（HTTP 探测），默认 20 秒一次。探测失败只把实例标记为不健康，不会删除，因为持久实例的信息落到了磁盘上，运维需要看到「这个节点出问题了」并手动处理。MySQL、Redis 这类基础设施适合持久实例，它们的地址不该因为一次探测失败就从注册表消失。</p><p data-src-line="95" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">两种模式对应两种一致性取舍。临时实例走 AP，注册信息写入内存即成功，牺牲一致性换可用性，适合实例频繁变化的场景。持久实例走 CP，通过 Raft 保证集群内数据一致，适合需要强一致的基础设施注册。</p><blockquote data-src-line="97" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><p data-src-line="97" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>踩坑提醒</strong>：<code>ephemeral: false</code> 一旦误设，会带来一次典型的线上事故。一个节点因为 GC 停顿导致心跳中断超过 30 秒，正常流程下它会被剔除，调用方不再把流量打到它。但持久实例不会被剔除，调用方继续往这个已经卡死的节点发请求，最终拖垮整条链路。业务服务不要设为持久实例。</p></blockquote><h2 id="_5-心跳与-grpc-长连接" tabindex="-1" data-src-line="99" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">5. 心跳与 gRPC 长连接 <a class="header-anchor" href="#_5-心跳与-grpc-长连接" aria-label="Permalink to &quot;5. 心跳与 gRPC 长连接&quot;">​</a></h2><p data-src-line="101" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">Nacos 2.x 把 1.x 的 HTTP 心跳换成了 gRPC 长连接。长连接让心跳不再是一次次独立的 HTTP 请求，客户端与服务端维持一条连接，心跳是连接上的保活信号。</p><p data-src-line="103" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">这个变化带出一个新的端口模型。2.x 在 8848 之外按固定偏移量派生出三个端口：</p><table tabindex="0"><thead data-src-line="105" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="105" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><th style="text-align:left;">端口</th><th style="text-align:left;">偏移量</th><th style="text-align:left;">用途</th></tr></thead><tbody data-src-line="107" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="107" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">8848</td><td style="text-align:left;">主端口</td><td style="text-align:left;">HTTP，控制台、OpenAPI</td></tr><tr data-src-line="108" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">9848</td><td style="text-align:left;">+1000</td><td style="text-align:left;">客户端 gRPC 请求服务端</td></tr><tr data-src-line="109" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">9849</td><td style="text-align:left;">+1001</td><td style="text-align:left;">服务端 gRPC 之间同步</td></tr><tr data-src-line="110" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">7848</td><td style="text-align:left;">-1000</td><td style="text-align:left;">Raft 选举，集群节点间</td></tr></tbody></table><blockquote data-src-line="112" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><p data-src-line="112" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>踩坑提醒</strong>：这是 2.x 升级最常见的故障源。很多环境的防火墙只放行了 8848，控制台能正常打开，但客户端注册服务时报 <code>Connection refused</code>，因为注册和心跳走的是 9848 这条 gRPC 连接。客户端与服务端之间至少放开 8848 和 9848。</p></blockquote><h2 id="_6-与负载均衡的衔接" tabindex="-1" data-src-line="114" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">6. 与负载均衡的衔接 <a class="header-anchor" href="#_6-与负载均衡的衔接" aria-label="Permalink to &quot;6. 与负载均衡的衔接&quot;">​</a></h2><p data-src-line="116" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">注册中心解决「有哪些实例」，负载均衡解决「选哪一个」。服务调用章节里的 <code>ServiceInstanceListSupplier</code> 就是从这个衔接点取数的，它内部向注册中心订阅服务名，拿到实时实例列表，再交给 <code>ReactorLoadBalancer</code> 挑一个。注册中心的实例列表每次变化都会推给订阅方，负载均衡拿到的永远是当前存活的那批地址。</p><h2 id="_7-注册中心选型" tabindex="-1" data-src-line="118" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">7. 注册中心选型 <a class="header-anchor" href="#_7-注册中心选型" aria-label="Permalink to &quot;7. 注册中心选型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="120" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="120" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><th style="text-align:left;">注册中心</th><th style="text-align:left;">一致性</th><th style="text-align:left;">健康检查</th><th style="text-align:left;">状态</th></tr></thead><tbody data-src-line="122" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><tr data-src-line="122" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">Nacos</td><td style="text-align:left;">AP（临时）/ CP（持久）</td><td style="text-align:left;">心跳 + 服务端探测</td><td style="text-align:left;">活跃</td></tr><tr data-src-line="123" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">Eureka</td><td style="text-align:left;">AP</td><td style="text-align:left;">心跳</td><td style="text-align:left;">已停止维护</td></tr><tr data-src-line="124" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">Consul</td><td style="text-align:left;">CP</td><td style="text-align:left;">服务端探测</td><td style="text-align:left;">活跃</td></tr><tr data-src-line="125" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><td style="text-align:left;">Zookeeper</td><td style="text-align:left;">CP</td><td style="text-align:left;">临时节点 + 心跳</td><td style="text-align:left;">活跃但偏重</td></tr></tbody></table><p data-src-line="127" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">Nacos 相对 Eureka 的额外价值在于一套组件同时覆盖服务发现和配置中心，且临时实例与持久实例的双模式能兼顾业务服务与基础设施两类场景。</p><h2 id="_8-生产注意事项" tabindex="-1" data-src-line="129" data-src-file="spring/09-distributed/chapter-03-service-discovery.md">8. 生产注意事项 <a class="header-anchor" href="#_8-生产注意事项" aria-label="Permalink to &quot;8. 生产注意事项&quot;">​</a></h2><ol data-src-line="131" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><li data-src-line="131" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>业务服务保持默认临时实例</strong>，不要设 <code>ephemeral: false</code>。</li><li data-src-line="132" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>防火墙至少放开 8848 和 9848</strong>，走 Nginx 或 SLB 时 9848 要配 TCP 转发，不能配 HTTP。</li><li data-src-line="133" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>保护阈值</strong>。服务健康实例占比跌破阈值时，Nacos 会把不健康实例也返回给调用方，避免流量全压到少数健康实例上引发雪崩。这个机制牺牲少量请求换整体可用，不要当成故障去「修复」。</li><li data-src-line="134" data-src-file="spring/09-distributed/chapter-03-service-discovery.md"><strong>命名空间隔离环境</strong>。dev、test、prod 用不同 namespace，跨 namespace 的服务互相不可见，能挡住一次配置错误导致的跨环境调用。</li></ol>`,31))])}const m=r(o,[["render",g]]);export{u as __pageData,m as default};
